using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Swashbuckle.AspNetCore.Annotations;using GraphApi.Models.VTS.VisitasGeneradas;using GraphApi.Services.VTS.VisitasGeneradas;namespace GraphApi.Controllers.VTS.VisitasGeneradas{    /// <summary>    /// Gestión de VisitasGeneradas: consulta, creación, actualización y borrado.    /// </summary>    [ApiController]    [Authorize]    [Route("VTS/[controller]")]    [Produces("application/json")]    [SwaggerTag("Operaciones sobre VisitasGeneradas")]    public class VisitasGeneradasController : Controller    {        private readonly IVisitasGeneradasService _objService;        public VisitasGeneradasController(IVisitasGeneradasService objService)        {            _objService = objService;        }        /// <summary>        /// Obtiene todos los VisitasGeneradas, con filtros opcionales.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="visitaGeneradaID">VisitaGeneradaID</param>        /// <param name="nombreVisitante">NombreVisitante</param>        /// <param name="usuarioVisitadoID">UsuarioVisitadoID</param>        /// <param name="nombreVisitado">NombreVisitado</param>        /// <param name="correoVisitado">CorreoVisitado</param>        /// <param name="casaID">CasaID</param>        /// <param name="direccionCasa">DireccionCasa</param>        /// <param name="numeroExtCasa">NumeroExtCasa</param>        /// <param name="tipoIdentificacionID">TipoIdentificacionID</param>        /// <param name="tipoIdentificacion">TipoIdentificacion</param>        /// <param name="numeroIdentificacion">NumeroIdentificacion</param>        /// <param name="rutaDocumento">RutaDocumento</param>        /// <param name="codigoQR">CodigoQR</param>        /// <param name="fechaEmision">FechaEmision</param>        /// <param name="fechaExpira">FechaExpira</param>        /// <param name="bUsado">bUsado</param>        /// <param name="bEliminado">bEliminado</param>        /// <returns>Listado de VisitasGeneradas</returns>        [HttpGet]        [SwaggerOperation(            Summary = "Listar VisitasGeneradas",            Description = "Devuelve VisitasGeneradas aplicando filtros opcionales."        )]        [ProducesResponseType(typeof(IEnumerable<clReadVisitasGeneradas>), StatusCodes.Status200OK)]        public async Task<ActionResult<IEnumerable<clReadVisitasGeneradas>>> GetAll(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromQuery] int? visitaGeneradaID,            [FromQuery] string? nombreVisitante,            [FromQuery] int? usuarioVisitadoID,            [FromQuery] string? nombreVisitado,            [FromQuery] string? correoVisitado,            [FromQuery] int? casaID,            [FromQuery] string? direccionCasa,            [FromQuery] string? numeroExtCasa,            [FromQuery] int? tipoIdentificacionID,            [FromQuery] string? tipoIdentificacion,            [FromQuery] string? numeroIdentificacion,            [FromQuery] string? rutaDocumento,            [FromQuery] string? codigoQR,            [FromQuery] DateTime? fechaEmision,            [FromQuery] DateTime? fechaExpira,            [FromQuery] bool? bUsado,            [FromQuery] bool? bEliminado,            [FromQuery] string? columnNames)        {            var vList = await _objService.GetVisitasGeneradasDynamic(                visitaGeneradaID,                 nombreVisitante,                 usuarioVisitadoID,                 nombreVisitado,                 correoVisitado,                 casaID,                 direccionCasa,                 numeroExtCasa,                 tipoIdentificacionID,                 tipoIdentificacion,                 numeroIdentificacion,                 rutaDocumento,                 codigoQR,                 fechaEmision,                 fechaExpira,                 bUsado,                 bEliminado,                 columnNames, nUserId, sWindowName);              return vList.Count()==0  ? NotFound() :  Ok(vList);        }        /// <summary>        /// Crea un nuevo VisitasGenerada.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="input">Datos del VisitasGenerada a crear.</param>        /// <returns>El VisitasGenerada recién creado.</returns>        [HttpPost]        [SwaggerOperation(            Summary = "Crear VisitasGeneradas",            Description = "Inserta un nuevo VisitasGenerada en la base de datos."        )]        [ProducesResponseType(typeof(clReadVisitasGeneradas), StatusCodes.Status201Created)]        public async Task<ActionResult<clReadVisitasGeneradas>> Create(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromBody] clCreateVisitasGeneradas objInput)        {            var vCreated = await _objService.CreateVisitasGeneradas(objInput, nUserId, sWindowName);            return vCreated is null ? NoContent() : vCreated;        }        /// <summary>        /// Actualización parcial de VisitasGenerada.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="input">Campos a actualizar y el ID del VisitasGenerada.</param>        /// <returns>El VisitasGenerada actualizado.</returns>        [HttpPatch]        [SwaggerOperation(            Summary = "Actualizar VisitasGeneradas",            Description = "Actualiza uno o varios campos de VisitasGenerada existente."        )]        [ProducesResponseType(typeof(clReadVisitasGeneradas), StatusCodes.Status200OK)]        public async Task<ActionResult<clReadVisitasGeneradas>> Patch(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromBody] clUpdateVisitasGeneradas objInput)        {            var vUpdated = await _objService.UpdateVisitasGeneradas(objInput, nUserId, sWindowName);            return vUpdated is null ? NotFound() : Ok(vUpdated);        }        /// <summary>        /// Elimina un VisitasGenerada por su ID.        /// </summary>        [HttpDelete("{nVisitasGeneradasID:int}")]        [SwaggerOperation(            Summary = "Eliminar VisitasGenerada",            Description = "Borra un VisitasGenerada si existe."        )]        [ProducesResponseType(StatusCodes.Status204NoContent)]        public async Task<IActionResult> Delete(int nVisitasGeneradasID)        {            var success = await _objService.DeleteVisitasGeneradas(nVisitasGeneradasID);            return success ? NoContent() : NotFound();        }    }}